query:
fragment UserSummary on User {
  id
  displayName
  role
  friends(first: 3) {
    id
    displayName
  }
}

fragment PostDetails on Post {
  id
  title
  tags
  author { ...UserSummary }
  comments(first: 2) {
    id
    body
    author { ...UserSummary }
  }
}

query Dashboard {
  me { ...UserSummary }
  posts(first: 5) {
    edges { node { ...PostDetails } }
  }
}
